import { useCallback } from "react";
import useFetch from "../use-fetch";
import { API_URL } from "../config";
import wrapperFetchJsonResponse from "../wrapper-fetch-json-response";
import { ActiveModuleRecord, Module, ModuleLifecycleRecord } from "../types/module";
import { RequestConfigType } from "./types/request-config";

/**
 * Read-only module endpoints.
 *
 * Only GETs live here on purpose. The backend exposes no
 * create/update/delete for modules — the registry is a build-time
 * artefact generated by `scripts/generate-module-registry.mjs` from the
 * `module.manifest.ts` of every entry under `src/modules`. Do not add
 * mutation services to this file; runtime enable/disable, install/upload,
 * and a module marketplace are explicit non-goals of the project.
 */
export type ModulesRequest = void;

export type ModulesResponse = Module[];

export function useGetModulesService() {
  const fetch = useFetch();

  return useCallback(
    (_data: ModulesRequest, requestConfig?: RequestConfigType) => {
      return fetch(`${API_URL}/v1/modules`, {
        method: "GET",
        ...requestConfig,
      }).then(wrapperFetchJsonResponse<ModulesResponse>);
    },
    [fetch]
  );
}

export type ModuleRequest = {
  id: Module["id"];
};

/**
 * `GET /v1/modules/:id` answers 200 with `null` for an unknown id — it does
 * not answer 404. Hence the `| null` in the response type.
 */
export type ModuleResponse = Module | null;

export function useGetModuleService() {
  const fetch = useFetch();

  return useCallback(
    (data: ModuleRequest, requestConfig?: RequestConfigType) => {
      return fetch(`${API_URL}/v1/modules/${data.id}`, {
        method: "GET",
        ...requestConfig,
      }).then(wrapperFetchJsonResponse<ModuleResponse>);
    },
    [fetch]
  );
}


